(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.15)*8 + Math.cos(sy*0.03+t*0.2)*6;
  const w2y = Math.cos(sy*0.028+t*0.18)*8 + Math.sin(sx*0.022-t*0.25)*6;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 2.1],
    [400+Math.cos(t*0.38+2)*70, 200+Math.sin(t*0.72)*50, 0.11, 1.8]
  ];
  let aS=0, iS=0, iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    iS2+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*0.6;
  }
  const act=aS/8, inh=iS/8, inh2=iS2/8;
  const fbm=(a,b,s)=>{
    let v=0,amp=1,freq=s;
    for(let i=0;i<3;i++){v+=Math.sin(a*freq+b*freq*0.7+t*(0.8+i*0.3))*amp;amp*=0.5;freq*=2.1;}
    return v;
  };
  const bg=fbm(dx,dy,0.04)+Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2),ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*0.9)*0.5)*0.3;
  const ring=Math.sin(dist*0.08-t*1.8)*Math.exp(-dist*0.004)*2;
  const diffusion=Math.sin((act-inh*0.6+inh2*0.3)*1.5+Math.sin(t*0.2)*0.3)*0.8;
  const reaction=Math.tanh((act-inh*0.5+bg*0.25+spiral+ring+diffusion)*2.0);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.25;
  const micro=Math.sin(dx*0.3+t*3)*Math.sin(dy*0.35-t*2.5)*0.15;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:1.0;
  const glow=Math.exp(-Math.abs(reaction)*0.5)*0.15;
  const blend=reaction*0.6+cell*0.2+micro*0.1+glow*0.1, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,90,120],[25,140,135],[60,175,130],
    [180,190,70],[210,155,55],[195,100,65],[165,55,60],[100,25,55],
    [45,15,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI)*0.15;
  const vig=1-Math.sqrt((x-cx)**2+(y-cy)**2)*0.0012;
  const L=Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*pulse*edge*vig))|0;
  const A=Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*pulse*edge*vig))|0;
  const B=Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*pulse*edge*vig))|0;
  return[L,A,B];
}
